window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-500e784bc10b243c"]={"versions": [{"id": "FIG-500e784bc10b243c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-/Bitfeld-Layout (Serialisierungs- und Datenstruktur-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Datenstroms („Data to Authenticate“) für die kryptografische Absicherung von Synchronisationsnachrichten (<em>Synchronization Messages</em>) im AUTOSAR-Modul <code>SecOC</code> (<em>Secure Onboard Communication</em>, Communication Services, Classic Platform).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als standardisierter Eingabepuffer für den Cryptographic Service Manager (<code>Csm_MacGenerate</code> / <code>Csm_MacVerify</code>), um Replay-Angriffe auf das Freshness Value Management (FVM) abzuwehren und Sender-/Empfänger-Zählerstände deterministisch abzugleichen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message ID (16 Bit):</strong></li>\n<li>Eindeutige Kennung der Synchronisations-PDU im SecOC-Kontext (<code>SecOCDataId</code>).</li>\n<li>Bildet das Präfix der zu authentifizierenden Daten.</li>\n<li><strong>Freshness Value (Gesamt: 40 Bit / 5 Bytes):</strong></li>\n<li><strong>Trip Counter (16 Bit):</strong> Langzeit-/Fahrzyklus-Zähler; inkrementiert pro Fahrzyklus/Startvorgang.</li>\n<li><strong>Reset Counter (20 Bit):</strong> Kurzzeit-/Epochenzähler; inkrementiert innerhalb eines Trip-Zyklus bzw. bei periodischen Synchronisationsintervallen.</li>\n<li><strong>0-Padding (4 Bit):</strong> Auffüllung mit Null-Bits im niederwertigsten Bereich (LSB-Ausrichtung), um die ungerade Bitbreite der Counter (16 + 20 = 36 Bit) auf eine ganzzahlige Byte-Grenze (5 Bytes) aufzurunden.</li>\n<li><strong>Strukturelle Beziehungen:</strong></li>\n<li>Die Gesamtlänge der Data-to-Authenticate-Eingangsstruktur beträgt $16\\,\\text{Bit} + 36\\,\\text{Bit} + 4\\,\\text{Bit} = 56\\,\\text{Bit}$ (7 Bytes).</li>\n<li>Das Padding ist integraler Bestandteil des Freshness-Feldes und geht direkt in die Hash-/MAC-Berechnung ein, wird jedoch in der Regel nicht zwingend über den Bus übertragen (je nach PDU-Layout der Synchronisationsnachricht).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sende- / Master-Pfad (Freshness Master ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ablauf des Synchronisations-Timers oder Zustandswechsel im FVM (z. B. Trip-Start).</li>\n<li><strong>Buffer Construction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auslesen des aktuellen <code>Trip Counter</code> (16 Bit) und <code>Reset Counter</code> (20 Bit) aus dem internen FVM-Speicher.</li>\n<li>Formatierung des Freshness-Werts unter bitweiser Verkettung und Anhängen von <code>0b0000</code> (4 Bit Zero-Padding).</li>\n<li>Voranstellen der konfigurierten <code>Message ID</code> (16 Bit, Big-Endian / Network Byte Order).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Krypto-Berechnung:</strong> Übergabe des 7-Byte-Puffers an <code>Csm_MacGenerate</code> (synchron oder asynchron via Callback).</li>\n<li><strong>PDU Transmission:</strong> Übertragung der Sync-PDU (Payload aus Counter-Werten + berechnetem MAC/Truncated MAC) via PduR an den CAN/Ethernet-Treiber.</li>\n</ol>\n<p class=\"fig-p\">#### B. Empfangs- / Slave-Pfad (Synchronizing ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR_SecOCCopyRxData</code> / <code>SecOC_RxIndication</code> der Synchronisations-PDU.</li>\n<li><strong>Rekonstruktion:</strong> Lokaler Aufbau desselben 56-Bit-Puffers aus empfangenen Counter-Werten, konfigurierter <code>Message ID</code> und dem identischen 4-Bit-Null-Padding.</li>\n<li><strong>Verifikation:</strong> Aufruf von <code>Csm_MacVerify</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Erfolg (<code>E_OK</code>):</strong> Aktualisierung der internen FVM-Zählerstände (Trip/Reset Counter) in der Slave-ECU.</li>\n<li><strong>Fehlschlag:</strong> Verwerfen der Synchronisation; Meldung an <code>Det</code> (<code>SECOC_E_CRYPTO_FAILURE</code>) bzw. Fehlereintrag via <code>Dem</code> bei persistenter Asynchronität.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>CSM-Byte-Alignment:</strong> Krypto-Treiber (z. B. AES-128-CMAC) operieren auf Oktett-Ebene (<code>uint8*</code>). Nicht byte-alignierte Bitlängen (36 Bit) führen ohne Padding zu Compiler-/Puffer-Inkonsistenzen. Das 4-Bit-Padding erzwingt die erforderliche Oktettausrichtung.</li>\n<li><strong>Endianness & Bit-Shifting:</strong></li>\n<li>Gemäß AUTOSAR-Standard gilt Big-Endian (Most Significant Bit first).</li>\n<li>Bei der Puffererstellung im FVM/SecOC-Treiber ist darauf zu achten, dass das Padding im letzten Byte in den niederwertigen Bits liegt (z. B. Bits 3..0 des 5. Freshness-Bytes als Nullen maskiert), damit die Krypto-Engine auf Sender- und Empfängerseite bit-identische Digests liefert.</li>\n<li><strong>Konfigurationsabgleich (ARXML):</strong></li>\n<li>Parameter <code>SecOCFreshnessValueLength</code> muss exakt mit der summierten Länge inkl. Padding (40 Bit) bzw. der FVM-Implementierung übereinstimmen.</li>\n<li>Diskrepanzen zwischen nativer Bitbreite der Zähler und konfiguriertem Padding führen zu MAC-Verifikationsfehlern ohne Bus-Übertragungsfehler.</li>\n</ul>"}, {"id": "FIG-2dd32ec7bf1b4153", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-/Bitfeld-Layout (Serialisierungs- und Datenstruktur-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Datenstroms („Data to Authenticate“) für die kryptografische Absicherung von Synchronisationsnachrichten (<em>Synchronization Messages</em>) im AUTOSAR-Modul <code>SecOC</code> (<em>Secure Onboard Communication</em>, Communication Services, Classic Platform).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als standardisierter Eingabepuffer für den Cryptographic Service Manager (<code>Csm_MacGenerate</code> / <code>Csm_MacVerify</code>), um Replay-Angriffe auf das Freshness Value Management (FVM) abzuwehren und Sender-/Empfänger-Zählerstände deterministisch abzugleichen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message ID (16 Bit):</strong></li>\n<li>Eindeutige Kennung der Synchronisations-PDU im SecOC-Kontext (<code>SecOCDataId</code>).</li>\n<li>Bildet das Präfix der zu authentifizierenden Daten.</li>\n<li><strong>Freshness Value (Gesamt: 40 Bit / 5 Bytes):</strong></li>\n<li><strong>Trip Counter (16 Bit):</strong> Langzeit-/Fahrzyklus-Zähler; inkrementiert pro Fahrzyklus/Startvorgang.</li>\n<li><strong>Reset Counter (20 Bit):</strong> Kurzzeit-/Epochenzähler; inkrementiert innerhalb eines Trip-Zyklus bzw. bei periodischen Synchronisationsintervallen.</li>\n<li><strong>0-Padding (4 Bit):</strong> Auffüllung mit Null-Bits im niederwertigsten Bereich (LSB-Ausrichtung), um die ungerade Bitbreite der Counter (16 + 20 = 36 Bit) auf eine ganzzahlige Byte-Grenze (5 Bytes) aufzurunden.</li>\n<li><strong>Strukturelle Beziehungen:</strong></li>\n<li>Die Gesamtlänge der Data-to-Authenticate-Eingangsstruktur beträgt $16\\,\\text{Bit} + 36\\,\\text{Bit} + 4\\,\\text{Bit} = 56\\,\\text{Bit}$ (7 Bytes).</li>\n<li>Das Padding ist integraler Bestandteil des Freshness-Feldes und geht direkt in die Hash-/MAC-Berechnung ein, wird jedoch in der Regel nicht zwingend über den Bus übertragen (je nach PDU-Layout der Synchronisationsnachricht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sende- / Master-Pfad (Freshness Master ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ablauf des Synchronisations-Timers oder Zustandswechsel im FVM (z. B. Trip-Start).</li>\n<li><strong>Buffer Construction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auslesen des aktuellen <code>Trip Counter</code> (16 Bit) und <code>Reset Counter</code> (20 Bit) aus dem internen FVM-Speicher.</li>\n<li>Formatierung des Freshness-Werts unter bitweiser Verkettung und Anhängen von <code>0b0000</code> (4 Bit Zero-Padding).</li>\n<li>Voranstellen der konfigurierten <code>Message ID</code> (16 Bit, Big-Endian / Network Byte Order).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Krypto-Berechnung:</strong> Übergabe des 7-Byte-Puffers an <code>Csm_MacGenerate</code> (synchron oder asynchron via Callback).</li>\n<li><strong>PDU Transmission:</strong> Übertragung der Sync-PDU (Payload aus Counter-Werten + berechnetem MAC/Truncated MAC) via PduR an den CAN/Ethernet-Treiber.</li>\n</ol>\n<p class=\"fig-p\">#### B. Empfangs- / Slave-Pfad (Synchronizing ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR_SecOCCopyRxData</code> / <code>SecOC_RxIndication</code> der Synchronisations-PDU.</li>\n<li><strong>Rekonstruktion:</strong> Lokaler Aufbau desselben 56-Bit-Puffers aus empfangenen Counter-Werten, konfigurierter <code>Message ID</code> und dem identischen 4-Bit-Null-Padding.</li>\n<li><strong>Verifikation:</strong> Aufruf von <code>Csm_MacVerify</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Erfolg (<code>E_OK</code>):</strong> Aktualisierung der internen FVM-Zählerstände (Trip/Reset Counter) in der Slave-ECU.</li>\n<li><strong>Fehlschlag:</strong> Verwerfen der Synchronisation; Meldung an <code>Det</code> (<code>SECOC_E_CRYPTO_FAILURE</code>) bzw. Fehlereintrag via <code>Dem</code> bei persistenter Asynchronität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>CSM-Byte-Alignment:</strong> Krypto-Treiber (z. B. AES-128-CMAC) operieren auf Oktett-Ebene (<code>uint8*</code>). Nicht byte-alignierte Bitlängen (36 Bit) führen ohne Padding zu Compiler-/Puffer-Inkonsistenzen. Das 4-Bit-Padding erzwingt die erforderliche Oktettausrichtung.</li>\n<li><strong>Endianness & Bit-Shifting:</strong></li>\n<li>Gemäß AUTOSAR-Standard gilt Big-Endian (Most Significant Bit first).</li>\n<li>Bei der Puffererstellung im FVM/SecOC-Treiber ist darauf zu achten, dass das Padding im letzten Byte in den niederwertigen Bits liegt (z. B. Bits 3..0 des 5. Freshness-Bytes als Nullen maskiert), damit die Krypto-Engine auf Sender- und Empfängerseite bit-identische Digests liefert.</li>\n<li><strong>Konfigurationsabgleich (ARXML):</strong></li>\n<li>Parameter <code>SecOCFreshnessValueLength</code> muss exakt mit der summierten Länge inkl. Padding (40 Bit) bzw. der FVM-Implementierung übereinstimmen.</li>\n<li>Diskrepanzen zwischen nativer Bitbreite der Zähler und konfiguriertem Padding führen zu MAC-Verifikationsfehlern ohne Bus-Übertragungsfehler.</li>\n</ul>"}, {"id": "FIG-5bdfbc39387e5242", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-/Bitfeld-Layout (Serialisierungs- und Datenstruktur-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Datenstroms („Data to Authenticate“) für die kryptografische Absicherung von Synchronisationsnachrichten (<em>Synchronization Messages</em>) im AUTOSAR-Modul <code>SecOC</code> (<em>Secure Onboard Communication</em>, Communication Services, Classic Platform).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als standardisierter Eingabepuffer für den Cryptographic Service Manager (<code>Csm_MacGenerate</code> / <code>Csm_MacVerify</code>), um Replay-Angriffe auf das Freshness Value Management (FVM) abzuwehren und Sender-/Empfänger-Zählerstände deterministisch abzugleichen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message ID (16 Bit):</strong></li>\n<li>Eindeutige Kennung der Synchronisations-PDU im SecOC-Kontext (<code>SecOCDataId</code>).</li>\n<li>Bildet das Präfix der zu authentifizierenden Daten.</li>\n<li><strong>Freshness Value (Gesamt: 40 Bit / 5 Bytes):</strong></li>\n<li><strong>Trip Counter (16 Bit):</strong> Langzeit-/Fahrzyklus-Zähler; inkrementiert pro Fahrzyklus/Startvorgang.</li>\n<li><strong>Reset Counter (20 Bit):</strong> Kurzzeit-/Epochenzähler; inkrementiert innerhalb eines Trip-Zyklus bzw. bei periodischen Synchronisationsintervallen.</li>\n<li><strong>0-Padding (4 Bit):</strong> Auffüllung mit Null-Bits im niederwertigsten Bereich (LSB-Ausrichtung), um die ungerade Bitbreite der Counter (16 + 20 = 36 Bit) auf eine ganzzahlige Byte-Grenze (5 Bytes) aufzurunden.</li>\n<li><strong>Strukturelle Beziehungen:</strong></li>\n<li>Die Gesamtlänge der Data-to-Authenticate-Eingangsstruktur beträgt $16\\,\\text{Bit} + 36\\,\\text{Bit} + 4\\,\\text{Bit} = 56\\,\\text{Bit}$ (7 Bytes).</li>\n<li>Das Padding ist integraler Bestandteil des Freshness-Feldes und geht direkt in die Hash-/MAC-Berechnung ein, wird jedoch in der Regel nicht zwingend über den Bus übertragen (je nach PDU-Layout der Synchronisationsnachricht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sende- / Master-Pfad (Freshness Master ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ablauf des Synchronisations-Timers oder Zustandswechsel im FVM (z. B. Trip-Start).</li>\n<li><strong>Buffer Construction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auslesen des aktuellen <code>Trip Counter</code> (16 Bit) und <code>Reset Counter</code> (20 Bit) aus dem internen FVM-Speicher.</li>\n<li>Formatierung des Freshness-Werts unter bitweiser Verkettung und Anhängen von <code>0b0000</code> (4 Bit Zero-Padding).</li>\n<li>Voranstellen der konfigurierten <code>Message ID</code> (16 Bit, Big-Endian / Network Byte Order).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Krypto-Berechnung:</strong> Übergabe des 7-Byte-Puffers an <code>Csm_MacGenerate</code> (synchron oder asynchron via Callback).</li>\n<li><strong>PDU Transmission:</strong> Übertragung der Sync-PDU (Payload aus Counter-Werten + berechnetem MAC/Truncated MAC) via PduR an den CAN/Ethernet-Treiber.</li>\n</ol>\n<p class=\"fig-p\">#### B. Empfangs- / Slave-Pfad (Synchronizing ECU)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR_SecOCCopyRxData</code> / <code>SecOC_RxIndication</code> der Synchronisations-PDU.</li>\n<li><strong>Rekonstruktion:</strong> Lokaler Aufbau desselben 56-Bit-Puffers aus empfangenen Counter-Werten, konfigurierter <code>Message ID</code> und dem identischen 4-Bit-Null-Padding.</li>\n<li><strong>Verifikation:</strong> Aufruf von <code>Csm_MacVerify</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Erfolg (<code>E_OK</code>):</strong> Aktualisierung der internen FVM-Zählerstände (Trip/Reset Counter) in der Slave-ECU.</li>\n<li><strong>Fehlschlag:</strong> Verwerfen der Synchronisation; Meldung an <code>Det</code> (<code>SECOC_E_CRYPTO_FAILURE</code>) bzw. Fehlereintrag via <code>Dem</code> bei persistenter Asynchronität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>CSM-Byte-Alignment:</strong> Krypto-Treiber (z. B. AES-128-CMAC) operieren auf Oktett-Ebene (<code>uint8*</code>). Nicht byte-alignierte Bitlängen (36 Bit) führen ohne Padding zu Compiler-/Puffer-Inkonsistenzen. Das 4-Bit-Padding erzwingt die erforderliche Oktettausrichtung.</li>\n<li><strong>Endianness & Bit-Shifting:</strong></li>\n<li>Gemäß AUTOSAR-Standard gilt Big-Endian (Most Significant Bit first).</li>\n<li>Bei der Puffererstellung im FVM/SecOC-Treiber ist darauf zu achten, dass das Padding im letzten Byte in den niederwertigen Bits liegt (z. B. Bits 3..0 des 5. Freshness-Bytes als Nullen maskiert), damit die Krypto-Engine auf Sender- und Empfängerseite bit-identische Digests liefert.</li>\n<li><strong>Konfigurationsabgleich (ARXML):</strong></li>\n<li>Parameter <code>SecOCFreshnessValueLength</code> muss exakt mit der summierten Länge inkl. Padding (40 Bit) bzw. der FVM-Implementierung übereinstimmen.</li>\n<li>Diskrepanzen zwischen nativer Bitbreite der Zähler und konfiguriertem Padding führen zu MAC-Verifikationsfehlern ohne Bus-Übertragungsfehler.</li>\n</ul>"}], "trans": [{"from": "FIG-500e784bc10b243c", "to": "FIG-2dd32ec7bf1b4153", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2dd32ec7bf1b4153", "to": "FIG-5bdfbc39387e5242", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
